const items = $input.all();
const body = (items[0] && items[0].json && (items[0].json.body || items[0].json)) || {};
const text = String(body.caller_text || body.message || body.transcript || body.query || '').toLowerCase();
const callId = String(body.call_id || body.conversation_id || 'unknown');
const phone = String(body.patient_phone || body.phone || body.cell_no || '');
const requestId = 'route_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
const nowIso = new Date().toISOString();
const SAFETY = ' If your symptoms are severe or get worse at any point, hang up and call 1122 immediately.';
// Broadened, bilingual (English + Roman Urdu) emergency detector, biased toward OVER-triage.
// A false positive only tells a patient to call 1122; a false negative routes an emergency to a routine slot. We accept the former to avoid the latter.
const emergencyRe = /(chest pain|heart attack|cardiac arrest|can ?not breathe|can'?t breathe|not breathing|can'?t catch (my )?breath|gasping|choking|severe bleeding|bleeding heavily|unconscious|uncons?ious|passed out|pass(ing)? out|blacked out|faint|collapse|no pulse|stroke|suicide|overdose|anaphylaxis|severe allergic|blue lips|turning blue|going blue|seizure|convuls|coughing (up )?blood|vomiting blood|blood in (my )?(vomit|stool)|heart (is )?racing|racing heart|going to die|feel like.*(die|dying)|drowning|severe pain|crushing pain|saans nahi|saans nai|saans ruk|dam ghut|behosh|be-?hosh|dil ka daura|dil bohat tez|dil bahut tez|seenay? me(i)?n dard|seene me(i)?n dard|khoon a ?raha|khoon araha)/i;
if (emergencyRe.test(text)) {
  const response = { ok: true, action: 'emergency_redirect', is_emergency: true, department: null, doctor_id: null, receptionist_message: 'This sounds like a medical emergency. Do not book a routine appointment. Please call 1122 (Rescue) immediately or go to the nearest emergency department.', emergency_number: '1122' };
  return [{ json: { response, audit: { event_type: 'route_call', request_id: requestId, call_id: callId, doctor_id: '', patient_phone: phone, payload_json: JSON.stringify(body).slice(0, 5000), severity: 'critical', created_iso: nowIso } } }];
}
const doctors = { ali_ent: { doctor_id: 'ali_ent', doctor_name: 'Dr Ali', department: 'ENT', pa_agent: 'Dr Ali ENT PA' }, khan_heart: { doctor_id: 'khan_heart', doctor_name: 'Dr Khan', department: 'Heart', pa_agent: 'Dr Khan Heart PA' }, ahmed_chest: { doctor_id: 'ahmed_chest', doctor_name: 'Dr Ahmed', department: 'Chest', pa_agent: 'Dr Ahmed Chest PA' } };
let doctor = null; let confidence = 0.2;
if (/(ear|nose|throat|ent|tonsil|sinus|hearing|voice|allergy|nasal)/i.test(text)) { doctor = doctors.ali_ent; confidence = 0.9; }
else if (/(heart|cardio|cardiac|bp|blood pressure|ecg|palpitation|hypertension)/i.test(text)) { doctor = doctors.khan_heart; confidence = 0.9; }
else if (/(chest|cough|lung|breath|breathing|asthma|pneumonia|wheez|sputum|tb|tuberculosis)/i.test(text)) { doctor = doctors.ahmed_chest; confidence = 0.88; }
const response = doctor ? { ok: true, action: 'transfer_to_pa', is_emergency: false, department: doctor.department, doctor_id: doctor.doctor_id, doctor_name: doctor.doctor_name, pa_agent: doctor.pa_agent, confidence, receptionist_message: 'I will connect you to ' + doctor.pa_agent + ' for appointment booking.' + SAFETY } : { ok: false, action: 'clarify_department', is_emergency: false, department: null, doctor_id: null, confidence, receptionist_message: 'I can help book ENT, Heart, or Chest OPD. Could you tell me the main symptom or which department you need?' + SAFETY };
return [{ json: { response, audit: { event_type: 'route_call', request_id: requestId, call_id: callId, doctor_id: doctor ? doctor.doctor_id : '', patient_phone: phone, payload_json: JSON.stringify(body).slice(0, 5000), severity: response.ok ? 'info' : 'warning', created_iso: nowIso } } }];

const items = $input.all();
const body = (items[0] && items[0].json && (items[0].json.body || items[0].json)) || {};
const doctors = { ali_ent: { doctor_id: 'ali_ent', doctor_name: 'Dr Ali', department: 'ENT', startHour: 9, endHour: 13, slotMinutes: 30 }, khan_heart: { doctor_id: 'khan_heart', doctor_name: 'Dr Khan', department: 'Heart', startHour: 10, endHour: 15, slotMinutes: 30 }, ahmed_chest: { doctor_id: 'ahmed_chest', doctor_name: 'Dr Ahmed', department: 'Chest', startHour: 11, endHour: 16, slotMinutes: 30 } };
const raw = String(body.doctor_id || body.department || '').toLowerCase();
let doctorId = doctors[raw] ? raw : raw.includes('heart') || raw.includes('cardio') ? 'khan_heart' : raw.includes('chest') || raw.includes('lung') || raw.includes('pulmo') ? 'ahmed_chest' : raw.includes('ent') || raw.includes('ear') || raw.includes('nose') || raw.includes('throat') ? 'ali_ent' : '';
const doctor = doctorId ? doctors[doctorId] : null;
const daysAhead = Math.min(Math.max(parseInt(body.days_ahead, 10) || 7, 1), 21);
const nowIso = new Date().toISOString();
const callId = String(body.call_id || body.conversation_id || '');
const phone = String(body.patient_phone || body.phone || body.cell_no || '');
const requestId = 'slots_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
return [{ json: { ctx: { doctor_id: doctorId, doctor_name: doctor ? doctor.doctor_name : '', department: doctor ? doctor.department : '', start_hour: doctor ? doctor.startHour : 0, end_hour: doctor ? doctor.endHour : 0, slot_minutes: doctor ? doctor.slotMinutes : 30, days_ahead: daysAhead, now_iso: nowIso, resolved: !!doctor, call_id: callId, patient_phone: phone, request_id: requestId, payload_json: JSON.stringify(body).slice(0, 5000) } } }];

const ctx = $('Normalize Slots').first().json.ctx;
const takenRows = $input.all().map(i => i.json).filter(r => r && r.slot_start);
// Compare instants, not strings. Postgres returns timestamptz normalised to UTC
// (2026-09-28T04:00:00+00:00) while the slots below are built as +05:00, so a string
// match would never fire and booked slots would keep being offered.
const takenSet = new Set(takenRows.map(r => new Date(r.slot_start).getTime()).filter(t => !Number.isNaN(t)));
const nowMs = Date.now();
function pad(n) { return String(n).padStart(2, '0'); }
function pktParts(ms) { const d = new Date(ms + 5 * 3600 * 1000); return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, day: d.getUTCDate(), dow: d.getUTCDay() }; }
const slots = [];
if (ctx.resolved) {
  for (let dayOffset = 0; dayOffset < ctx.days_ahead && slots.length < 6; dayOffset++) {
    const p = pktParts(nowMs + dayOffset * 86400000);
    if (p.dow === 0 || p.dow === 6) continue;
    const datePart = p.y + '-' + pad(p.m) + '-' + pad(p.day);
    for (let hour = ctx.start_hour; hour < ctx.end_hour && slots.length < 6; hour++) {
      for (let minute = 0; minute < 60 && slots.length < 6; minute += ctx.slot_minutes) {
        const start = datePart + 'T' + pad(hour) + ':' + pad(minute) + ':00+05:00';
        const startMs = new Date(start).getTime();
        if (startMs <= nowMs) continue;
        if (takenSet.has(startMs)) continue;
        const endTotal = minute + ctx.slot_minutes;
        const endHour = hour + Math.floor(endTotal / 60);
        const endMin = endTotal % 60;
        const end = datePart + 'T' + pad(endHour) + ':' + pad(endMin) + ':00+05:00';
        slots.push({ slot_start: start, slot_end: end, display: datePart + ' ' + pad(hour) + ':' + pad(minute) + ' PKT' });
      }
    }
  }
}
const response = ctx.resolved ? { ok: true, doctor_id: ctx.doctor_id, doctor_name: ctx.doctor_name, department: ctx.department, timezone: 'Asia/Karachi', available_slots: slots, slots_count: slots.length, message: slots.length ? ('I have ' + slots.length + ' available slots for ' + ctx.doctor_name + '.') : ('No open slots for ' + ctx.doctor_name + ' in the next ' + ctx.days_ahead + ' days.') } : { ok: false, doctor_id: '', available_slots: [], slots_count: 0, message: 'Could not identify the department. Please specify ENT, Heart, or Chest.' };
return [{ json: { response, audit: { event_type: 'check_slots', request_id: ctx.request_id, call_id: ctx.call_id, doctor_id: ctx.doctor_id, patient_phone: ctx.patient_phone, payload_json: ctx.payload_json, severity: ctx.resolved ? 'info' : 'warning', created_iso: ctx.now_iso } } }];

const items = $input.all();
const body = (items[0] && items[0].json && (items[0].json.body || items[0].json)) || {};
const doctors = { ali_ent: { doctor_id: 'ali_ent', doctor_name: 'Dr Ali', department: 'ENT', startHour: 9, endHour: 13, slotMinutes: 30 }, khan_heart: { doctor_id: 'khan_heart', doctor_name: 'Dr Khan', department: 'Heart', startHour: 10, endHour: 15, slotMinutes: 30 }, ahmed_chest: { doctor_id: 'ahmed_chest', doctor_name: 'Dr Ahmed', department: 'Chest', startHour: 11, endHour: 16, slotMinutes: 30 } };
function normPhone(v) { let s = String(v || '').replace(/[^0-9+]/g, ''); if (s.startsWith('+')) { s = '+' + s.slice(1).replace(/[+]/g, ''); } else if (s.startsWith('00')) { s = '+' + s.slice(2); } else if (s.startsWith('0')) { s = '+92' + s.slice(1); } else if (s.startsWith('92')) { s = '+' + s; } else if (s.length > 0) { s = '+92' + s; } return s; }
// DST-safe PKT wall-clock via the IANA tz database (no hardcoded +05:00 offset).
function pktParts(ms) { const f = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Karachi', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', weekday: 'short', hour12: false }).formatToParts(new Date(ms)).reduce((a, p) => (a[p.type] = p.value, a), {}); return { y: +f.year, mo: +f.month, day: +f.day, hour: (f.hour === '24' ? 0 : +f.hour), min: +f.minute, sec: +f.second, dow: f.weekday }; }
function pad(n) { return String(n).padStart(2, '0'); }
const doctorId = String(body.doctor_id || '').toLowerCase();
const doctor = doctors[doctorId] || null;
const patientName = String(body.patient_name || body.name || '').trim();
const patientPhone = normPhone(body.patient_phone || body.phone || body.cell_no || '');
const slotStart = String(body.slot_start || body.selected_slot || '').trim();
const callId = String(body.call_id || body.conversation_id || '');
const nowIso = new Date().toISOString();
const requestId = 'book_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
const reasons = [];
if (!doctor) reasons.push('unknown_or_missing_doctor_id');
if (!patientName) reasons.push('missing_patient_name');
if (!/^[+]92[0-9]{10}$/.test(patientPhone)) reasons.push('invalid_phone');
const startMs = slotStart ? new Date(slotStart).getTime() : NaN;
if (!slotStart || isNaN(startMs)) { reasons.push('missing_or_invalid_slot_start'); } else { if (startMs <= Date.now()) reasons.push('slot_in_the_past'); if (doctor) { const p = pktParts(startMs); if (p.dow === 'Sat' || p.dow === 'Sun') reasons.push('slot_on_weekend'); if (!(p.hour >= doctor.startHour && p.hour < doctor.endHour)) reasons.push('slot_outside_clinic_hours'); if (p.min % doctor.slotMinutes !== 0 || p.sec !== 0) reasons.push('slot_not_on_grid'); } }
let slotEnd = String(body.slot_end || '').trim();
let slotDisplay = '';
if (doctor && !isNaN(startMs)) { if (!slotEnd) { slotEnd = new Date(startMs + doctor.slotMinutes * 60000).toISOString(); } const p = pktParts(startMs); slotDisplay = p.y + '-' + pad(p.mo) + '-' + pad(p.day) + ' ' + pad(p.hour) + ':' + pad(p.min) + ' PKT'; }
const valid = reasons.length === 0;
const ctx = { valid, reasons, doctor_id: doctorId, doctor_name: doctor ? doctor.doctor_name : '', department: doctor ? doctor.department : '', patient_name: patientName, patient_phone: patientPhone, slot_start: slotStart, slot_end: slotEnd, slot_display: slotDisplay, call_id: callId, request_id: requestId, now_iso: nowIso, payload_json: JSON.stringify(Object.assign({}, body, { patient_phone: patientPhone })).slice(0, 5000) };
return [{ json: { valid, ctx } }];

const c = $('Validate Booking').first().json.ctx;
const inserted = $input.first().json || {};
const apptId = inserted.id !== undefined ? inserted.id : null;
const response = { ok: true, status: 'confirmed', appointment_id: apptId, doctor_id: c.doctor_id, doctor_name: c.doctor_name, department: c.department, patient_name: c.patient_name, patient_phone: c.patient_phone, slot_start: c.slot_start, slot_end: c.slot_end, slot_display: c.slot_display, timezone: 'Asia/Karachi', sms_status: 'verbal_confirmed', pa_message: 'Appointment confirmed with ' + c.doctor_name + ' (' + c.department + ') on ' + c.slot_display + '. Read this confirmation aloud to the patient and ask them to arrive 10 minutes early. No SMS is sent yet.' };
return [{ json: { response, audit: { event_type: 'book_confirmed', request_id: c.request_id, call_id: c.call_id, doctor_id: c.doctor_id, patient_phone: c.patient_phone, payload_json: c.payload_json, severity: 'info', created_iso: c.now_iso } } }];

const c = $('Validate Booking').first().json.ctx;
const errItem = $input.first().json || {};
const errMsg = String((errItem.error && (errItem.error.message || errItem.error)) || errItem.message || '').toLowerCase();
const isConflict = errMsg.includes('duplicate') || errMsg.includes('unique') || errMsg.includes('23505') || errMsg.includes('already exists') || errMsg.includes('conflict');
let response; let audit;
if (isConflict) {
  response = { ok: false, status: 'slot_unavailable', doctor_id: c.doctor_id, doctor_name: c.doctor_name, department: c.department, requested_slot: c.slot_start, slot_display: c.slot_display, timezone: 'Asia/Karachi', sms_status: 'not_sent', pa_message: 'That slot was just taken by another patient. Tell the patient it is no longer available, then call check-slots again to offer the next open time for ' + c.doctor_name + '.' };
  audit = { event_type: 'book_conflict', request_id: c.request_id, call_id: c.call_id, doctor_id: c.doctor_id, patient_phone: c.patient_phone, payload_json: c.payload_json, severity: 'warning', created_iso: c.now_iso };
} else {
  response = { ok: false, status: 'system_error', doctor_id: c.doctor_id, timezone: 'Asia/Karachi', sms_status: 'not_sent', pa_message: 'A temporary system error stopped the booking. Apologise to the patient and ask them to try again in a moment. Do not tell them the slot is taken.' };
  audit = { event_type: 'book_error', request_id: c.request_id, call_id: c.call_id, doctor_id: c.doctor_id, patient_phone: c.patient_phone, payload_json: JSON.stringify({ ctx_payload: c.payload_json, error: errMsg }).slice(0, 5000), severity: 'error', created_iso: c.now_iso };
}
return [{ json: { response, audit } }];

const c = $('Validate Booking').first().json.ctx;
const reasonText = { unknown_or_missing_doctor_id: 'the department or doctor was not recognised', missing_patient_name: 'the patient name is missing', invalid_phone: 'the phone number is not a valid Pakistani mobile number (must be +92 followed by exactly 10 digits)', missing_or_invalid_slot_start: 'the appointment time is missing or invalid', slot_in_the_past: 'the requested time is in the past', slot_on_weekend: 'the requested day falls on a weekend when the clinic is closed', slot_outside_clinic_hours: 'the requested time is outside the doctor clinic hours', slot_not_on_grid: 'the requested time does not line up with a real 30-minute appointment slot' };
const human = (c.reasons || []).map(r => reasonText[r] || r).join('; ');
const response = { ok: false, status: 'rejected_invalid_request', reasons: c.reasons, doctor_id: c.doctor_id, timezone: 'Asia/Karachi', sms_status: 'not_sent', pa_message: 'I could not confirm the booking because ' + human + '. Please collect the correct details and try again. Required: department or doctor, patient full name, a valid +92 phone number, and a future appointment time that falls within clinic hours on a weekday.' };
return [{ json: { response, audit: { event_type: 'book_rejected', request_id: c.request_id, call_id: c.call_id, doctor_id: c.doctor_id, patient_phone: c.patient_phone, payload_json: c.payload_json, severity: 'warning', created_iso: c.now_iso } } }];
